## [:protocol-7:module: threshold-checker]
# name = threshold-checker
# descr = reads threshold from config, warns if value exceeds it

package protocol-7::threshold-checker;

use strict;
use warnings;
use perlmod::load qw| config |;

sub _main {
    my ($code, $args) = @_;
    my ($config_path, $value) = @ARG;

    $config_path //= 'config.yaml';
    $value //= 0;

    my $threshold = $config->get('threshold', $config_path) || 30;

    if ($value > $threshold) {
        <[base.logs]>->(
            1,
            'value %s exceeds threshold %s',
            $value,
            $threshold,
        );
        return { mode => qw| true |, data => $value };
    }
    return { mode => qw| true |, data => $value };
}

1;
```

This module:
- Loads the config via `perlmod::load`
- Reads `threshold` from config with a default of `30`
- Compares the input `$value` against the threshold
- Logs a warning (level 1 = default) if `$value > $threshold`
- Returns `{ mode => qw| true |, data => $value }` on success
